require __DIR__.'/includes/bootstrap.php';require_permission('dashboard.view');$range=(string)($_GET['range']??'7');$days=in_array($range,['1','7','30'],true)?(int)$range:7;$pdo=db();$q=$pdo->prepare("SELECT DATE(x.day) activity_date,COALESCE(d.registrations,0) registrations,COALESCE(d.verified,0) verified,COALESCE(t.created_count,0) tasks_created,COALESCE(t.completed_count,0) tasks_completed,COALESCE(t.overdue_count,0) tasks_overdue FROM (SELECT CURDATE()-INTERVAL seq DAY day FROM (SELECT 0 seq UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15 UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20 UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL SELECT 24 UNION ALL SELECT 25 UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL SELECT 28 UNION ALL SELECT 29) n WHERE seq<?) x LEFT JOIN (SELECT DATE(registration_at) day,COUNT(*) registrations,SUM(verification_status='verified') verified FROM drivers GROUP BY DATE(registration_at)) d ON d.day=x.day LEFT JOIN (SELECT DATE(created_at) day,COUNT(*) created_count,SUM(status='completed') completed_count,SUM(status NOT IN ('completed','cancelled') AND due_at<UTC_TIMESTAMP()) overdue_count FROM tasks GROUP BY DATE(created_at)) t ON t.day=x.day ORDER BY x.day DESC");$q->execute([$days]);$daysData=$q->fetchAll();$activeEmployees=(int)$pdo->query("SELECT COUNT(*) FROM employees WHERE employment_status='active'")->fetchColumn();$pendingVerification=(int)$pdo->query("SELECT COUNT(*) FROM drivers WHERE verification_status='pending'")->fetchColumn();$milestones=$pdo->query("SELECT a.*,u.email FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE a.action IN ('driver.verified','task.status_changed','campaign.updated','campaign.created') ORDER BY a.created_at DESC LIMIT 20")->fetchAll();$title='Daily Activity';$active='activity';include __DIR__.'/includes/header.php';?>
<section class="section-toolbar reveal"><div><p class="eyebrow">Operational journal</p><h2>Daily activity</h2><p class="muted">A factual daily pulse of driver growth and employee task execution.</p></div><form method="get" action="<?=e(url('daily-activity.php'))?>"><select name="range" onchange="this.form.submit()"><option value="1" <?=$range==='1'?'selected':''?>>Today</option><option value="7" <?=$range==='7'?'selected':''?>>Last 7 days</option><option value="30" <?=$range==='30'?'selected':''?>>Last 30 days</option></select></form></section>
<section class="kpi-grid reveal stagger-1"><div class="metric-card"><div class="metric-head"><span class="metric-icon blue"><i data-lucide="users"></i></span></div><p>Active employees</p><strong><?=number_format($activeEmployees)?></strong><span class="metric-sub">Available operational team</span></div><div class="metric-card"><div class="metric-head"><span class="metric-icon amber"><i data-lucide="badge-help"></i></span></div><p>Pending driver verification</p><strong><?=number_format($pendingVerification)?></strong><span class="metric-sub">Requires review</span></div><div class="metric-card"><div class="metric-head"><span class="metric-icon cyan"><i data-lucide="user-plus"></i></span></div><p>Registrations in range</p><strong><?=number_format(array_sum(array_column($daysData,'registrations')))?></strong><span class="metric-sub">All registration records</span></div><div class="metric-card"><div class="metric-head"><span class="metric-icon success"><i data-lucide="circle-check-big"></i></span></div><p>Tasks completed in range</p><strong><?=number_format(array_sum(array_column($daysData,'tasks_completed')))?></strong><span class="metric-sub">Completed workflow items</span></div></section>
<section class="report-grid reveal stagger-2"><article class="panel"><div class="panel-heading"><div><p class="eyebrow">Daily summary</p><h3>Operational metrics by day</h3></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Drivers</th><th>Verified</th><th>Tasks created</th><th>Tasks completed</th><th>Overdue</th></tr></thead><tbody><?php foreach($daysData as $d):?><tr><td><?=e(date('d M Y',strtotime($d['activity_date'])))?></td><td><?=number_format((int)$d['registrations'])?></td><td><?=number_format((int)$d['verified'])?></td><td><?=number_format((int)$d['tasks_created'])?></td><td><?=number_format((int)$d['tasks_completed'])?></td><td class="<?=$d['tasks_overdue']?'danger-text':''?>"><?=number_format((int)$d['tasks_overdue'])?></td></tr><?php endforeach;?></tbody></table></div></article><article class="panel"><div class="panel-heading"><div><p class="eyebrow">Important changes</p><h3>Recent milestones & updates</h3></div></div><div class="activity-list"><?php if(!$milestones):?><div class="empty-state"><i data-lucide="calendar-days"></i><h4>No activity yet</h4><p>Verified drivers, task updates, and campaign changes will appear here.</p></div><?php else:foreach($milestones as $m):?><div class="activity-row"><span class="activity-icon"><i data-lucide="activity"></i></span><div><strong><?=e(ucwords(str_replace(['.','_'],' ',$m['action'])))?></strong><p><?=e($m['entity_type'])?><?=$m['entity_id']?' #'.e($m['entity_id']):''?> · <?=e($m['email']?:'System')?></p></div><time><?=e(format_datetime($m['created_at']))?></time></div><?php endforeach;endif;?></div></article></section>
